import csv
import io


def parse_csv(raw_csv: str):
    width = 8
    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    records = list(
        csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter=",",
            quotechar='"',
            doublequote=True,
        )
    )

    first_nonblank = None
    header_index = None
    for index, record in enumerate(records):
        if not any(field.strip() for field in record):
            continue
        if first_nonblank is None:
            first_nonblank = index
        if len(record) == width and all(field.strip() for field in record):
            header_index = index
            break

    if header_index is None:
        header_index = first_nonblank
    if header_index is None:
        return {"columns": [], "rows": []}

    def normalize(record):
        if len(record) > width:
            return record[:width - 1] + [",".join(record[width - 1:])]
        return record + [""] * (width - len(record))

    return {
        "columns": normalize(records[header_index]),
        "rows": [normalize(record) for record in records[header_index + 1:]],
    }
